    country: 'US',
    state: 'LA',
    alertLevel: 'high',
    sources: ['Louisiana Department of Insurance'],
    sourceUrl: 'https://ldi.la.gov/news/press-releases/4-21-26-ldi-warns-consumers-against-unlicensed-healthcare-entities',
