    sources: ["Mississippi Attorney General's Office", 'WLBT', "U.S. Attorney's Office for the Northern District of Mississippi"],
    sourceUrl: 'https://attorneygenerallynnfitch.com/2026/06/29/ag-fitch-announces-sentencing-in-786k-healthcare-fraud-scheme-june-29-2026/',
